        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");

    const Hero = () => `
      <header class="hero">
        <div class="eyebrow">Cat care and behavior</div>
        <h1>Frequently asked questions about cats</h1>
        <p>
          Explore quick answers about common feline habits, routines, and personality quirks.
          Each question starts collapsed and opens on demand for a clean, focused reading experience.
        </p>
      </header>
    `;

    const FAQItem = ({ question, answer }, index) => `
      <div class="example">
        <button
          class="question-button"
          type="button"
          aria-expanded="false"
          aria-controls="details-${index}"
          data-toggle="details-${index}"
        >
          <span class="question-copy">
            <span class="question-label">Question ${index + 1}</span>
            <span class="question-text">${escapeHtml(question)}</span>
          </span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="details-${index}" hidden>
          <p>${escapeHtml(answer)}</p>
        </div>
      </div>
    `;

    const FAQList = (items) => `
      <section class="faq-list" aria-label="Cat frequently asked questions">
        ${items.map(FAQItem).join("")}
      </section>
    `;

    const App = () => `
      <main class="page-shell">
        ${Hero()}
        ${FAQList(faqs)}
      </main>
    `;

    const root = document.getElementById("app");
    root.innerHTML = App();

    root.addEventListener("click", (event) => {
      const button = event.target.closest("[data-toggle]");
      if (!button) return;

      const contentId = button.getAttribute("data-toggle");
      const details = document.getElementById(contentId);
      const isExpanded = button.getAttribute("aria-expanded") === "true";

      button.setAttribute("aria-expanded", String(!isExpanded));
      details.hidden = isExpanded;
    });
  </script>
</body>
</html>
