  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(20, 27, 48, 0.9);
      --panel-strong: rgba(29, 39, 67, 0.98);
      --border: rgba(148, 163, 184, 0.22);
      --text: #e5eefc;
      --muted: #99a8c7;
      --accent: #8b5cf6;
      --accent-strong: #a78bfa;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(139, 92, 246, 0.22), transparent 35%),
        radial-gradient(circle at 85% 15%, rgba(34, 211, 238, 0.16), transparent 22%),
        linear-gradient(180deg, #09101d 0%, #0d1324 45%, #070b15 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 40px 20px;
    }

    .page-shell {
      width: min(920px, 100%);
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.88), rgba(10, 14, 27, 0.96));
      border: 1px solid var(--border);
      border-radius: 28px;
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(18px);
    }

    .hero {
      padding: 48px 48px 28px;
      border-bottom: 1px solid rgba(148, 163, 184, 0.16);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(139, 92, 246, 0.12);
      color: #d6c8ff;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 18px 0 12px;
      font-size: clamp(2.4rem, 4vw, 4rem);
      line-height: 1.02;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      display: grid;
      gap: 18px;
      padding: 28px;
    }

    .example {
      background: linear-gradient(180deg, var(--panel), var(--panel-strong));
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 20px;
      overflow: hidden;
      transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
    }

    .example:hover {
      transform: translateY(-1px);
      border-color: rgba(167, 139, 250, 0.4);
      box-shadow: 0 16px 32px rgba(2, 6, 23, 0.32);
    }

    .question-button {
      width: 100%;
      border: 0;
      background: transparent;
      color: inherit;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      padding: 22px 24px;
      text-align: left;
      cursor: pointer;
      font: inherit;
    }

    .question-copy {
      display: grid;
      gap: 6px;
    }

    .question-label {
      color: var(--accent-strong);
      font-size: 0.8rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      font-weight: 700;
    }

    .question-text {
      font-size: 1.1rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .icon {
      flex: 0 0 auto;
      width: 40px;
      height: 40px;
      border-radius: 999px;
      display: grid;
      place-items: center;
      background: rgba(139, 92, 246, 0.14);
      border: 1px solid rgba(167, 139, 250, 0.24);
      color: #ddd6fe;
      transition: transform 180ms ease, background 180ms ease;
      font-size: 1.2rem;
      font-weight: 700;
    }

    .question-button[aria-expanded="true"] .icon {
      transform: rotate(45deg);
      background: rgba(139, 92, 246, 0.22);
    }

    .details {
      padding: 0 24px 24px;
      color: #d4def3;
      line-height: 1.75;
    }

    .details[hidden] {
      display: none;
    }

    .details p {
      margin: 0;
    }

    @media (max-width: 720px) {
      .hero {
        padding: 32px 24px 20px;
      }

      .faq-list {
        padding: 20px;
      }

      .question-button {
        padding: 18px 18px;
      }

      .details {
        padding: 0 18px 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel calm, comfortable, or affectionate, but purring can also be a way to self-soothe when they are stressed or recovering. It is a versatile sound that can signal contentment, communication, and comfort all at once."
      },
      {
        question: "Why do cats knead with their paws?",
        answer: "Kneading is a behavior that starts in kittenhood while nursing. Many adult cats keep doing it because it is comforting and instinctive. They may knead blankets, laps, or beds when they feel safe and relaxed."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most cats sleep between 12 and 16 hours a day, and some nap even longer. Their sleep habits reflect their natural predator rhythm: conserve energy, then become active in short bursts to play, explore, or hunt."
      },
      {
        question: "Why do cats stare out windows for so long?",
        answer: "A window gives a cat a front-row seat to birds, insects, moving shadows, and neighborhood activity. It provides mental stimulation, entertainment, and a safe way to observe the world without leaving home."
      },
      {
        question: "What makes a cat feel secure at home?",
        answer: "Cats thrive when they have predictable routines, quiet resting places, vertical spaces to climb, and easy access to food, water, and litter areas. A calm environment with gentle interaction helps them feel safe and confident."
      }
    ];

    const escapeHtml = (value) =>
      value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");

    const Hero = () => `
      <header class="hero">
        <div class="eyebrow">Cat care and behavior</div>
        <h1>Frequently asked questions about cats</h1>
        <p>
          Explore quick answers about common feline habits, routines, and personality quirks.
          Each question starts collapsed and opens on demand for a clean, focused reading experience.
        </p>
      </header>
    `;

    const FAQItem = ({ question, answer }, index) => `
      <div class="example">
        <button
          class="question-button"
          type="button"
          aria-expanded="false"
          aria-controls="details-${index}"
          data-toggle="details-${index}"
        >
          <span class="question-copy">
            <span class="question-label">Question ${index + 1}</span>
            <span class="question-text">${escapeHtml(question)}</span>
          </span>
          <span class="icon" aria-hidden="true">+</span>
        </button>
        <div class="details" id="details-${index}" hidden>
          <p>${escapeHtml(answer)}</p>
        </div>
      </div>
    `;

    const FAQList = (items) => `
      <section class="faq-list" aria-label="Cat frequently asked questions">
        ${items.map(FAQItem).join("")}
      </section>
    `;

    const App = () => `
      <main class="page-shell">
        ${Hero()}
        ${FAQList(faqs)}
      </main>
    `;

    const root = document.getElementById("app");
    root.innerHTML = App();

    root.addEventListener("click", (event) => {
      const button = event.target.closest("[data-toggle]");
      if (!button) return;

      const contentId = button.getAttribute("data-toggle");
      const details = document.getElementById(contentId);
      const isExpanded = button.getAttribute("aria-expanded") === "true";

      button.setAttribute("aria-expanded", String(!isExpanded));
      details.hidden = isExpanded;
    });
  </script>
</body>
</html>
